From d7334f490d63511594825d24edd765563abd5c80 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:18:04 +0100
Subject: [PATCH] actions/dpms: turn off the locked screen when dimming has the
 same delay

KIdleTime keeps one idle notification per length, so the lock timeout
joined the dimming one and never fired if that had already gone off. Add
1 ms until no other timeout has that length, so it counts from the lock.

BUG: 527667
---
 daemon/actions/bundled/dpms.cpp | 10 ++++++++--
 1 file changed, 8 insertions(+), 2 deletions(-)

diff --git a/daemon/actions/bundled/dpms.cpp b/daemon/actions/bundled/dpms.cpp
index 2b8ec6e60..aa51cd767 100644
--- a/daemon/actions/bundled/dpms.cpp
+++ b/daemon/actions/bundled/dpms.cpp
@@ -21,6 +21,7 @@

 #include <KActionCollection>
 #include <KGlobalAccel>
+#include <KIdleTime>
 #include <KLocalizedString>
 #include <KPluginFactory>
 #include <KSharedConfig>
@@ -219,8 +220,13 @@ void DPMS::onScreenLockerActiveChanged(bool active)

     if (m_isActivatingLock) {
         // entering lockscreen - fast display turn-off if the config calls for it
-        qCDebug(POWERDEVIL) << "DPMS: registering idle timeout (screen lock activating) after" << m_idleTimeoutWhenActivatingLock;
-        registerIdleTimeout(m_idleTimeoutWhenActivatingLock);
+        std::chrono::milliseconds timeout = m_idleTimeoutWhenActivatingLock;
+        const QList<int> registeredTimeouts = KIdleTime::instance()->idleTimeouts().values();
+        while (registeredTimeouts.contains(timeout.count())) {
+            timeout += 1ms;
+        }
+        qCDebug(POWERDEVIL) << "DPMS: registering idle timeout (screen lock activating) after" << timeout;
+        registerIdleTimeout(timeout);
         // if we're locking but about to suspend, wait until onResumeFromSuspend() to register the timeout
     } else if (!active) {
         // restoring normal idleTimeout
